              ]
            },
            {
              "id": "p4-s1",
              "source": "The result is the familiar arch.",
              "translation_vi": "Kết quả là vòng cung quen thuộc mà chúng ta thấy.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "the familiar arch",
                  "target": "vòng cung quen thuộc"
                }
              ]
            },
            {
              "id": "p4-s2",
              "source": "The colours always appear in the same order, with red on the outside and violet on the inside.",
              "translation_vi": "Các màu luôn xuất hiện theo cùng một thứ tự, với đỏ ở ngoài cùng và tím ở trong cùng.",
              "precision": "sentence",
              "phrases": [
