          "translation_sha256": "b36fba77e5d5a9fd16f3e57b54cd6a73995221e4ce4eb8cc02f60375f88732d2",
          "units": [
            {
              "id": "p1-s1",
              "source": "For decades, space travel was the preserve of a handful of trained astronauts chosen by governments.",
              "translation_vi": "Suốt nhiều thập kỷ, du hành không gian là lĩnh vực dành riêng cho một số ít phi hành gia được đào tạo và chính phủ lựa chọn.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "the preserve of",
                  "target": "lĩnh vực dành riêng cho"
                },
                {
                  "source": "a handful of trained astronauts",
                  "target": "một số ít phi hành gia được đào tạo"
                }
              ]
            },
            {
              "id": "p1-s2",
              "source": "That began to change in 2021, when private citizens who had bought tickets crossed the boundary of space on craft built by private companies.",
              "translation_vi": "Điều đó bắt đầu đổi năm 2021, khi công dân tư nhân mua vé vượt ranh giới không gian trên phương tiện do công ty tư nhân chế tạo.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "private citizens",
                  "target": "công dân tư nhân"
                },
                {
                  "source": "the boundary of space",
                  "target": "ranh giới không gian"
                },
                {
                  "source": "craft built by private companies",
                  "target": "phương tiện do công ty tư nhân chế tạo"
                }
              ]
            },
            {
              "id": "p1-s3",
              "source": "A young space-tourism industry was born, and with it a stubborn question: whether firing the rich into the sky for a few minutes is really worth it.",
              "translation_vi": "Ngành du lịch không gian non trẻ ra đời, cùng câu hỏi dai dẳng: phóng người giàu lên trời vài phút có thật sự đáng hay không.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "A young space-tourism industry",
                  "target": "Ngành du lịch không gian non trẻ"
                },
                {
                  "source": "a stubborn question",
                  "target": "câu hỏi dai dẳng"
                },
                {
                  "source": "really worth it",
                  "target": "thật sự đáng"
                }
              ]
            },
            {
              "id": "p2-s1",
              "source": "The cost, in every sense, is high.",
              "translation_vi": "Cái giá, theo mọi nghĩa, đều cao.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "The cost",
                  "target": "Cái giá"
                },
                {
                  "source": "in every sense",
                  "target": "theo mọi nghĩa"
                }
              ]
            },
            {
              "id": "p2-s2",
              "source": "A seat on a brief suborbital flight — one that merely touches the edge of space and falls back — can run to hundreds of thousands of dollars, and longer trips into orbit cost far more.",
              "translation_vi": "Một chỗ trong chuyến bay dưới quỹ đạo ngắn — chỉ chạm rìa không gian rồi rơi về — có thể lên tới hàng trăm nghìn đô la, còn chuyến vào quỹ đạo dài hơn tốn hơn nhiều.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "a brief suborbital flight",
                  "target": "chuyến bay dưới quỹ đạo ngắn"
                },
                {
                  "source": "hundreds of thousands of dollars",
                  "target": "hàng trăm nghìn đô la"
                },
                {
                  "source": "longer trips into orbit",
                  "target": "chuyến vào quỹ đạo dài hơn"
                }
              ]
            },
            {
              "id": "p2-s3",
              "source": "At such prices, critics argue, the money could be better spent on more pressing problems at home.",
              "translation_vi": "Người phản đối lập luận rằng ở mức giá ấy, tiền có thể được dùng tốt hơn cho các vấn đề cấp bách hơn ở quê nhà.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "critics argue",
                  "target": "Người phản đối lập luận"
                },
                {
                  "source": "more pressing problems at home",
                  "target": "các vấn đề cấp bách hơn ở quê nhà"
                }
              ]
            },
            {
              "id": "p3-s1",
              "source": "There are serious risks to weigh, too.",
              "translation_vi": "Cũng có những rủi ro nghiêm trọng cần cân nhắc.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "serious risks to weigh",
                  "target": "những rủi ro nghiêm trọng cần cân nhắc"
                }
              ]
            },
            {
              "id": "p3-s2",
              "source": "Rockets are dangerous machines, and even with careful checks an accident remains possible.",
              "translation_vi": "Tên lửa là máy móc nguy hiểm, và dù kiểm tra kỹ vẫn có thể xảy ra tai nạn.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "even with careful checks",
                  "target": "dù kiểm tra kỹ"
                },
                {
                  "source": "an accident remains possible",
                  "target": "vẫn có thể xảy ra tai nạn"
                }
              ]
            },
            {
              "id": "p3-s3",
              "source": "There are environmental worries as well: rockets release gases and soot high in the atmosphere, where their effects are still poorly understood.",
              "translation_vi": "Còn có lo ngại môi trường: tên lửa thải khí và muội than lên cao trong khí quyển, nơi tác động của chúng vẫn chưa được hiểu rõ.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "gases and soot",
                  "target": "khí và muội than"
                },
                {
                  "source": "high in the atmosphere",
                  "target": "lên cao trong khí quyển"
                },
                {
                  "source": "still poorly understood",
                  "target": "vẫn chưa được hiểu rõ"
                }
              ]
            },
            {
              "id": "p3-s4",
              "source": "For some, polluting the sky so that a few people can enjoy the view is hard to justify.",
              "translation_vi": "Với một số người, gây ô nhiễm bầu trời để ít người được ngắm cảnh là khó biện minh.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "For some",
                  "target": "Với một số người"
                },
                {
                  "source": "hard to justify",
                  "target": "khó biện minh"
                }
              ]
            },
            {
              "id": "p4-s1",
              "source": "Supporters, however, point to benefits that may reach beyond the travellers themselves.",
              "translation_vi": "Tuy nhiên, người ủng hộ chỉ ra lợi ích có thể vượt ra ngoài bản thân du khách.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "Supporters",
                  "target": "người ủng hộ"
                },
                {
                  "source": "may reach beyond the travellers themselves",
                  "target": "có thể vượt ra ngoài bản thân du khách"
                }
              ]
            },
            {
              "id": "p4-s2",
              "source": "The race for customers has driven the development of reusable rockets, which may lower the cost of other missions, including scientific research.",
              "translation_vi": "Cuộc đua giành khách thúc đẩy phát triển tên lửa tái sử dụng, có thể hạ chi phí các sứ mệnh khác, kể cả nghiên cứu khoa học.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "reusable rockets",
                  "target": "tên lửa tái sử dụng"
                },
                {
                  "source": "may lower the cost",
                  "target": "có thể hạ chi phí"
                },
                {
                  "source": "including scientific research",
                  "target": "kể cả nghiên cứu khoa học"
                }
              ]
            },
            {
              "id": "p4-s3",
              "source": "The flights also carry experiments and help test technology that could later serve more distant journeys.",
              "translation_vi": "Các chuyến bay còn mang thí nghiệm và giúp thử công nghệ có thể phục vụ hành trình xa hơn về sau.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "carry experiments",
                  "target": "mang thí nghiệm"
                },
                {
                  "source": "test technology",
                  "target": "thử công nghệ"
                },
                {
                  "source": "more distant journeys",
                  "target": "hành trình xa hơn"
                }
              ]
            },
            {
              "id": "p4-s4",
              "source": "For these people, today's tourists are quietly paying for tomorrow's progress.",
              "translation_vi": "Với những người này, khách du lịch hôm nay đang âm thầm trả tiền cho tiến bộ ngày mai.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "For these people",
                  "target": "Với những người này"
                },
                {
                  "source": "paying for tomorrow's progress",
                  "target": "trả tiền cho tiến bộ ngày mai"
                }
              ]
            },
            {
              "id": "p5-s1",
              "source": "So is space tourism worth it?",
              "translation_vi": "Vậy du lịch không gian có đáng không?",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "is space tourism worth it",
                  "target": "du lịch không gian có đáng không"
                }
              ]
            },
            {
              "id": "p5-s2",
              "source": "The answer probably depends on how one weighs a rare, if frivolous, experience against its price and its risks.",
              "translation_vi": "Câu trả lời có lẽ tùy cách cân một trải nghiệm hiếm, dù phù phiếm, với giá và rủi ro của nó.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "probably depends",
                  "target": "có lẽ tùy"
                },
                {
                  "source": "a rare, if frivolous, experience",
                  "target": "một trải nghiệm hiếm, dù phù phiếm"
                },
                {
                  "source": "its price and its risks",
                  "target": "giá và rủi ro của nó"
                }
              ]
            },
            {
              "id": "p5-s3",
              "source": "Whether the industry matures into something more broadly useful, or remains an expensive game for the few, is too early to say.",
              "translation_vi": "Còn quá sớm để nói ngành này sẽ trưởng thành thành thứ có ích rộng rãi hơn hay vẫn là trò đắt đỏ của số ít.",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "something more broadly useful",
                  "target": "thứ có ích rộng rãi hơn"
                },
                {
                  "source": "an expensive game for the few",
                  "target": "trò đắt đỏ của số ít"
                },
                {
                  "source": "too early to say",
                  "target": "Còn quá sớm để nói"
                }
              ]
            }
